const stemCache=new Map();
function fft(re,im,inverse=false){const n=re.length;for(let i=1,j=0;i<n;i++){let bit=n>>1;for(;j&bit;bit>>=1)j^=bit;j^=bit;if(i<j){[re[i],re[j]]=[re[j],re[i]];[im[i],im[j]]=[im[j],im[i]]}}for(let len=2;len<=n;len<<=1){const angle=(inverse?2:-2)*Math.PI/len,wlr=Math.cos(angle),wli=Math.sin(angle);for(let i=0;i<n;i+=len){let wr=1,wi=0;for(let j=0;j<len/2;j++){const a=i+j,b=a+len/2,tr=re[b]*wr-im[b]*wi,ti=re[b]*wi+im[b]*wr;re[b]=re[a]-tr;im[b]=im[a]-ti;re[a]+=tr;im[a]+=ti;const next=wr*wlr-wi*wli;wi=wr*wli+wi*wlr;wr=next}}}if(inverse)for(let i=0;i<n;i++){re[i]/=n;im[i]/=n}}
function vocalBandWeight(hz){if(hz<70||hz>15000)return .03;if(hz<140)return .03+(hz-70)/70*.37;if(hz<220)return .4+(hz-140)/80*.45;if(hz<7000)return 1;return Math.max(.12,1-(hz-7000)/8000*.88)}
function stemSettings(profile,strength){const amount=strength/100;if(profile==='vocal')return{threshold:.27-.10*amount,power:1.25,subtract:.98,smooth:.38};if(profile==='music')return{threshold:.46-.06*amount,power:2.15,subtract:.72+.18*amount,smooth:.25};return{threshold:.36-.08*amount,power:1.65,subtract:.82+.16*amount,smooth:.32}}
async function separateSpectral(source,clip,profile,strength,onProgress){initAudio();const sr=source.sampleRate,start=Math.max(0,Math.floor((clip.offset||0)*sr)),wanted=Math.max(1,Math.floor(clip.duration*(clip.rate||1)*sr)),length=Math.min(wanted,source.length-start),fftSize=2048,hop=512,bins=fftSize/2+1,frames=Math.max(1,Math.ceil((length+fftSize)/hop)),settings=stemSettings(profile,strength),left=source.getChannelData(0),right=source.numberOfChannels>1?source.getChannelData(1):left,stereo=source.numberOfChannels>1,vocalL=new Float64Array(length+fftSize),vocalR=new Float64Array(length+fftSize),norm=new Float64Array(length+fftSize),previous=new Float32Array(bins),window=new Float64Array(fftSize);for(let i=0;i<fftSize;i++)window[i]=.5-.5*Math.cos(2*Math.PI*i/(fftSize-1));const lr=new Float64Array(fftSize),li=new Float64Array(fftSize),rr=new Float64Array(fftSize),ri=new Float64Array(fftSize),vr=new Float64Array(fftSize),vi=new Float64Array(fftSize);for(let frame=0;frame<frames;frame++){const pos=frame*hop;for(let i=0;i<fftSize;i++){const ix=start+pos+i,w=window[i];lr[i]=(ix<start+length?left[ix]:0)*w;rr[i]=(ix<start+length?right[ix]:0)*w;li[i]=ri[i]=0}fft(lr,li);fft(rr,ri);for(let k=0;k<bins;k++){const ml=Math.hypot(lr[k],li[k]),mr=Math.hypot(rr[k],ri[k]),sum=ml+mr+1e-12,balance=1-Math.abs(ml-mr)/sum,coherence=stereo?Math.max(0,(lr[k]*rr[k]+li[k]*ri[k])/(ml*mr+1e-12)):0.62,center=Math.pow(Math.max(0,balance*coherence),settings.power),band=vocalBandWeight(k*sr/fftSize);let mask=Math.max(0,Math.min(1,(center*band-settings.threshold)/(1-settings.threshold)));mask=mask*mask*(3-2*mask);mask=mask*(1-settings.smooth)+previous[k]*settings.smooth;previous[k]=mask;vr[k]=(lr[k]+rr[k])*.5*mask;vi[k]=(li[k]+ri[k])*.5*mask;if(k>0&&k<fftSize/2){vr[fftSize-k]=vr[k];vi[fftSize-k]=-vi[k]}}fft(vr,vi,true);for(let i=0;i<fftSize&&pos+i<vocalL.length;i++){const w=window[i],v=vr[i]*w;vocalL[pos+i]+=v;vocalR[pos+i]+=v;norm[pos+i]+=w*w}if(frame%10===0){onProgress(Math.min(.98,(frame+1)/frames));await new Promise(r=>setTimeout(r,0))}}const vocals=ctx.createBuffer(2,length,sr),music=ctx.createBuffer(2,length,sr),voL=vocals.getChannelData(0),voR=vocals.getChannelData(1),muL=music.getChannelData(0),muR=music.getChannelData(1);let peak=0;for(let i=0;i<length;i++){const n=norm[i]||1,vL=vocalL[i]/n,vR=vocalR[i]/n;voL[i]=vL;voR[i]=vR;muL[i]=left[start+i]-vL*settings.subtract;muR[i]=right[start+i]-vR*settings.subtract;peak=Math.max(peak,Math.abs(voL[i]),Math.abs(voR[i]),Math.abs(muL[i]),Math.abs(muR[i]))}if(peak>1){const gain=.98/peak;for(let i=0;i<length;i++){voL[i]*=gain;voR[i]*=gain;muL[i]*=gain;muR[i]*=gain}}onProgress(1);return{vocal:vocals,instrument:music}}
function addStemTrack(mode,sourceClip,buffer){const label=mode==='vocal'?'Vocal Stem':'Instrumental Stem',t=makeTrack(label),raw=encodeWav(buffer),stem={id:uid(),trackId:t.id,name:`${sourceClip.name} — ${mode==='vocal'?'Vocals':'Instrumental'}`,start:sourceClip.start,offset:0,duration:buffer.duration/(sourceClip.rate||1),rate:sourceClip.rate||1,buffer,peaks:getPeaks(buffer),raw};clips.push(stem);return stem}
async function runStems(mode){const sourceClip=clips.find(c=>c.id===selectedClip);if(!sourceClip?.buffer)return toast('Select an audio clip first');const profile=$('#stemProfile').value,strength=+$('#stemStrength').value,key=`${sourceClip.id}:${sourceClip.offset||0}:${sourceClip.duration}:${sourceClip.rate||1}:${profile}:${strength}`,buttons=['#vocalStemBtn','#instrumentStemBtn','#bothStemsBtn'].map($);buttons.forEach(b=>b.disabled=true);remember();try{$('#stemStatus').textContent='Analyzing overlapping spectral windows…';let result=stemCache.get(key);if(!result){result=await separateSpectral(sourceClip.buffer,sourceClip,profile,strength,p=>{$('#stemProgressBar').style.width=`${Math.round(p*100)}%`;$('#stemStatus').textContent=`Separating mix… ${Math.round(p*100)}%`});stemCache.clear();stemCache.set(key,result)}if(mode==='both'){addStemTrack('vocal',sourceClip,result.vocal);addStemTrack('instrument',sourceClip,result.instrument)}else addStemTrack(mode,sourceClip,result[mode]);selectedClip=clips.at(-1).id;markDirty();render();$('#stemStatus').textContent='Stem processing complete.';toast(mode==='both'?'Vocal and instrumental stems created':'Stem track created')}catch(error){console.error(error);$('#stemStatus').textContent='This clip could not be separated. Try a shorter stereo clip.'}finally{buttons.forEach(b=>b.disabled=false)}}
let demucsJob=null,demucsPoll=null;
function clipAsWav(clip){const sr=clip.buffer.sampleRate,start=Math.max(0,Math.floor((clip.offset||0)*sr)),length=Math.max(1,Math.min(Math.floor(clip.duration*(clip.rate||1)*sr),clip.buffer.length-start)),out=ctx.createBuffer(Math.min(2,clip.buffer.numberOfChannels),length,sr);for(let ch=0;ch<out.numberOfChannels;ch++)out.copyToChannel(clip.buffer.getChannelData(ch).subarray(start,start+length),ch);return encodeWav(out)}
async function checkDemucs(){try{const response=await fetch('/api/health',{cache:'no-store'}),data=await response.json();if(!response.ok)throw new Error('Local companion did not respond');if(!data.ready)throw new Error(data.error||'Demucs dependencies are incomplete');$('#demucsDot').classList.add('online');$('#demucsConnection').textContent=`Demucs ${data.version||''} ready`;$('#demucsRunBtn').disabled=false;$('#demucsHelp').textContent='Audio stays on this computer. The first separation downloads the selected AI model.';return true}catch(error){$('#demucsDot').classList.remove('online');$('#demucsConnection').textContent='Local Demucs engine is offline';$('#demucsRunBtn').disabled=true;$('#demucsHelp').innerHTML=`${escapeHtml(error.message||'Demucs is unavailable')}<br>Run <strong>Install-Demucs.bat</strong>, then <strong>Start-Open-Wave.bat</strong>.`;return false}}
function setDemucsBusy(busy){$('.stems-body').classList.toggle('processing',busy);$('#demucsRunBtn').disabled=busy;$('#demucsCancelBtn').disabled=!busy;$('#closeStemsBtn').disabled=busy}
async function parseStemBundle(blob){const bytes=new Uint8Array(await blob.arrayBuffer()),view=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength),headerLength=view.getUint32(0,true),header=JSON.parse(new TextDecoder().decode(bytes.subarray(4,4+headerLength)));let offset=4+headerLength;const stems=[];for(const item of header.stems){const chunk=bytes.slice(offset,offset+item.length);offset+=item.length;const buffer=await ctx.decodeAudioData(chunk.buffer);let peak=0;for(let ch=0;ch<buffer.numberOfChannels;ch++){const data=buffer.getChannelData(ch),stride=Math.max(1,Math.floor(data.length/20000));for(let i=0;i<data.length;i+=stride)peak=Math.max(peak,Math.abs(data[i]))}if(peak<1e-5)throw new Error(`${item.name} was silent`);stems.push({name:item.name,buffer})}return stems}
function addDemucsStem(name,sourceClip,buffer){const title=name==='no_vocals'?'Instrumental':name[0].toUpperCase()+name.slice(1),t=makeTrack(`${title} Stem`),stem={id:uid(),trackId:t.id,name:`${sourceClip.name} — ${title}`,start:sourceClip.start,offset:0,duration:buffer.duration/(sourceClip.rate||1),rate:sourceClip.rate||1,buffer,peaks:getPeaks(buffer),raw:encodeWav(buffer)};clips.push(stem);return stem}
async function pollDemucs(sourceClip){try{const response=await fetch(`/api/jobs/${demucsJob}`,{cache:'no-store'}),job=await response.json();if(!response.ok)throw new Error(job.detail||'Could not read Demucs job');const progress=Math.max(2,Math.min(99,job.progress||2));$('#stemProgressBar').style.width=`${progress}%`;$('#stemStatus').textContent=job.message||`Separating with Demucs… ${progress}%`;if(job.status==='failed')throw new Error(job.error||'Demucs separation failed');if(job.status==='cancelled'){finishDemucs('Separation cancelled.');return}if(job.status!=='complete'){demucsPoll=setTimeout(()=>pollDemucs(sourceClip),900);return}const result=await fetch(`/api/jobs/${demucsJob}/result`);if(!result.ok)throw new Error('Could not retrieve separated stems');const stems=await parseStemBundle(await result.blob());remember();for(const stem of stems)addDemucsStem(stem.name,sourceClip,stem.buffer);selectedClip=clips.at(-1)?.id||selectedClip;markDirty();render();$('#stemProgressBar').style.width='100%';finishDemucs(`${stems.length} Demucs stems added to the timeline.`);toast('AI stems added')}catch(error){console.error(error);finishDemucs(error.message||'Demucs separation failed.')}}
function finishDemucs(message){clearTimeout(demucsPoll);demucsPoll=null;demucsJob=null;setDemucsBusy(false);$('#stemStatus').textContent=message;checkDemucs()}
async function runDemucs(){const sourceClip=clips.find(c=>c.id===selectedClip);if(!sourceClip?.buffer)return toast('Select an audio clip first');if(!await checkDemucs())return;initAudio();setDemucsBusy(true);$('#stemProgressBar').style.width='2%';$('#stemStatus').textContent='Uploading the selected clip to local Demucs…';try{const form=new FormData();form.append('audio',new Blob([clipAsWav(sourceClip)],{type:'audio/wav'}),'mix.wav');form.append('mode',$('#demucsMode').value);const response=await fetch('/api/jobs',{method:'POST',body:form}),data=await response.json();if(!response.ok)throw new Error(data.detail||'Could not start Demucs');demucsJob=data.id;pollDemucs(sourceClip)}catch(error){finishDemucs(error.message||'Could not start Demucs')}}
async function cancelDemucs(){if(!demucsJob)return;$('#stemStatus').textContent='Cancelling…';try{await fetch(`/api/jobs/${demucsJob}`,{method:'DELETE'})}catch{}finishDemucs('Separation cancelled.')}
function wireStems(){const strength=$('#stemStrength');strength.oninput=()=>$('#stemStrengthOut').textContent=`${strength.value}%`;$('#stemsBtn').onclick=()=>{const c=clips.find(x=>x.id===selectedClip);if(!c)return toast('Select a mix clip first');$('#stemSourceName').textContent=c.name;$('#stemStatus').textContent='';$('#stemProgressBar').style.width='0';$('#stemsDialog').showModal();checkDemucs()};$('#closeStemsBtn').onclick=()=>$('#stemsDialog').close();$('#demucsRunBtn').onclick=runDemucs;$('#demucsCancelBtn').onclick=cancelDemucs;$('#vocalStemBtn').onclick=()=>runStems('vocal');$('#instrumentStemBtn').onclick=()=>runStems('instrument');$('#bothStemsBtn').onclick=()=>runStems('both');checkDemucs()}
wireStems();
